// Auto-generated by file split — part of the D&D 5e Character Sheet project
// Edit this file directly to add or modify weapon and equipment reference data.

const WEAPONS = {
  'Club': {dmg:'1d4', type:'bludgeoning'},
  'Dagger': {dmg:'1d4', type:'piercing', finesse:true},
  'Greatclub': {dmg:'1d8', type:'bludgeoning'},
  'Handaxe': {dmg:'1d6', type:'slashing'},
  'Javelin': {dmg:'1d6', type:'piercing'},
  "Light Hammer": {dmg:'1d4', type:'bludgeoning'},
  'Mace': {dmg:'1d6', type:'bludgeoning'},
  'Quarterstaff': {dmg:'1d6', type:'bludgeoning'},
  'Sickle': {dmg:'1d4', type:'slashing', finesse:true},
  'Spear': {dmg:'1d6', type:'piercing'},
  'Light Crossbow': {dmg:'1d8', type:'piercing', ranged:true},
  'Dart': {dmg:'1d4', type:'piercing', finesse:true, ranged:true},
  'Shortbow': {dmg:'1d6', type:'piercing', ranged:true},
  'Sling': {dmg:'1d4', type:'bludgeoning', ranged:true}
};

const MARTIAL_WEAPONS = {
  'Longsword': {dmg:'1d8', type:'slashing'},
  'Shortsword': {dmg:'1d6', type:'piercing', finesse:true},
  'Rapier': {dmg:'1d8', type:'piercing', finesse:true},
  'Warhammer': {dmg:'1d8', type:'bludgeoning'},
  'Battleaxe': {dmg:'1d8', type:'slashing'},
  'Greatsword': {dmg:'2d6', type:'slashing'},
  'Halberd': {dmg:'1d10', type:'slashing'}
};

// ============================================================================
// Weapons panel — sidebar view onto the existing #attacksTable rows (that
// table stays the single source of truth / editor, same pattern as the
// Spellbook onto #spellsTable). Self-contained: doesn't touch js/app.js.
// Also wires the Actions-section collapse/reveal toggle since it lives in
// the same part of the page and needed no app.js changes either.
// ============================================================================

(function(){

  function _d(nSides){ return 1 + Math.floor(Math.random() * nSides); }

  function rollDiceExpression(expr){
    if(!expr) return null;
    const terms = expr.match(/[+-]?[^+-]+/g) || [];
    let total = 0;
    const parts = [];
    terms.forEach(raw=>{
      const trimmed = raw.trim();
      const sign = trimmed.startsWith('-') ? -1 : 1;
      const term = trimmed.replace(/^[+-]/, '').trim();
      const diceMatch = term.match(/^(\d+)d(\d+)$/i);
      if(diceMatch){
        const n = parseInt(diceMatch[1],10), s = parseInt(diceMatch[2],10);
        const rolls = [];
        for(let i=0;i<n;i++) rolls.push(_d(s));
        const sum = rolls.reduce((a,b)=>a+b,0);
        total += sign*sum;
        parts.push(`${sign<0?'-':''}${n}d${s} [${rolls.join('+')}]`);
      } else if(/^\d+$/.test(term)){
        const val = parseInt(term,10);
        total += sign*val;
        parts.push(`${sign<0?'-':'+'}${val}`);
      } else if(term){
        parts.push(term);
      }
    });
    return { total, breakdown: parts.join(' ') };
  }

  // Pulls the leading "NdM[+/-K]" chunk out of a damage/type string like
  // "1d8+4 slashing" so the dice part can be rolled and the rest shown as-is.
  function splitDamageString(str){
    if(!str) return { dice:null, rest:'' };
    const m = str.match(/^\s*((?:\d+d\d+)(?:\s*[+-]\s*\d+)?)\s*(.*)$/i);
    if(!m) return { dice:null, rest:str };
    return { dice: m[1].replace(/\s+/g,''), rest: m[2].trim() };
  }

  function lookupWeaponData(name){
    if(!name) return null;
    const key = Object.keys(WEAPONS||{}).find(k => k.toLowerCase() === name.trim().toLowerCase());
    if(key) return WEAPONS[key];
    const mkey = Object.keys(MARTIAL_WEAPONS||{}).find(k => k.toLowerCase() === name.trim().toLowerCase());
    if(mkey) return MARTIAL_WEAPONS[mkey];
    return null;
  }

  function _rowData(tr){
    return {
      name: tr.querySelector('.atk-name').value.trim(),
      bonus: tr.querySelector('.atk-bonus').value.trim(),
      dmg: tr.querySelector('.atk-dmg').value.trim()
    };
  }
  function getAllAttackRows(){
    const body = document.querySelector('#attacksTable tbody');
    if(!body) return [];
    return [...body.querySelectorAll('tr')].map(_rowData).filter(r => r.name);
  }

  function openWeaponModal(kicker, title, bodyHtml){
    const overlay = document.getElementById('spellModalOverlay');
    if(!overlay) return;
    document.getElementById('spellModalKicker').textContent = kicker;
    document.getElementById('spellModalTitle').textContent = title;
    document.getElementById('spellModalBody').innerHTML = bodyHtml;
    overlay.style.display = 'flex';
  }

  function buildRollContent(row){
    const { dice, rest } = splitDamageString(row.dmg);
    const bonusNum = parseInt((row.bonus||'').replace(/[^\d+-]/g,''), 10);
    let html = '';
    if(!isNaN(bonusNum)){
      const roll = _d(20);
      html += `<div class="roll-line">Attack roll: <span class="roll-total">${roll + bonusNum}</span> (d20: ${roll} ${bonusNum>=0?'+':'-'} ${Math.abs(bonusNum)})</div>`;
    } else if(row.bonus){
      html += `<div class="roll-line">Attack bonus on sheet: ${row.bonus} (couldn't parse a number — roll a raw d20 and add it yourself).</div>`;
    }
    if(dice){
      const result = rollDiceExpression(dice);
      if(result){
        html += `<div class="roll-line">Damage (${dice}${rest?`, ${rest}`:''}): <span class="roll-total">${result.total}</span><br><span class="roll-note" style="margin-top:0;">${result.breakdown}</span></div>`;
      }
    } else if(row.dmg){
      html += `<div class="roll-line">Damage on sheet: ${row.dmg} (not a plain dice expression — roll manually).</div>`;
    }
    return html || `<div class="desc-text">No bonus or damage set on this row yet.</div>`;
  }

  function buildInfoContent(row){
    const data = lookupWeaponData(row.name);
    let html = `<div class="roll-line">Bonus: ${row.bonus || '—'}<br>Damage: ${row.dmg || '—'}</div>`;
    if(data){
      const props = [];
      if(data.finesse) props.push('finesse');
      if(data.versatile) props.push(`versatile (${data.versatile})`);
      if(data.twoHanded) props.push('two-handed');
      if(data.light) props.push('light');
      if(data.heavy) props.push('heavy');
      if(data.reach) props.push('reach');
      if(data.thrown) props.push('thrown');
      html += `<div class="desc-text">Base weapon: ${data.dmg} ${data.type}${props.length?` — ${props.join(', ')}`:''}.</div>`;
    } else {
      html += `<div class="desc-text">Custom entry — no matching base weapon in the reference list, showing sheet values only.</div>`;
    }
    return html;
  }

  function getWeaponBadge(row){
    const bonusNum = parseInt((row.bonus||'').replace(/[^\d+-]/g,''), 10);
    return isNaN(bonusNum) ? '' : `🎯 ${bonusNum>=0?'+':''}${bonusNum}`;
  }

  function renderWeaponsList(){
    const container = document.getElementById('weaponsList');
    if(!container) return;
    const rows = getAllAttackRows();
    if(!rows.length){
      container.innerHTML = `<div class="spellbook-empty">No weapons/attacks added yet — add some in Attacks &amp; Cantrips, then open this panel to use them here.</div>`;
      return;
    }
    container.innerHTML = rows.map(r=>{
      const badge = getWeaponBadge(r);
      return `<div class="spellbook-item" data-name="${r.name.replace(/"/g,'&quot;')}">
        <div class="sb-name"><span class="sb-title">${r.name}</span></div>
        ${badge?`<span class="sb-badge">${badge}</span>`:''}
        <button type="button" class="sb-roll" title="Roll">🎲</button>
      </div>`;
    }).join('');

    container.querySelectorAll('.spellbook-item').forEach(item=>{
      const name = item.dataset.name;
      const row = rows.find(r => r.name === name);
      item.querySelector('.sb-name').addEventListener('click', ()=>{
        openWeaponModal('Details', name, buildInfoContent(row));
      });
      item.querySelector('.sb-roll').addEventListener('click', (e)=>{
        e.stopPropagation();
        openWeaponModal('Roll', name, buildRollContent(row));
      });
    });
  }

  function openWeapons(){
    renderWeaponsList();
    document.getElementById('weaponsOverlay').style.display = 'flex';
  }
  function closeWeapons(){
    document.getElementById('weaponsOverlay').style.display = 'none';
  }

  function wireWeaponsChrome(){
    const openBtn = document.getElementById('btnOpenWeapons');
    const closeBtn = document.getElementById('btnCloseWeapons');
    const overlay = document.getElementById('weaponsOverlay');
    if(openBtn) openBtn.addEventListener('click', openWeapons);
    if(closeBtn) closeBtn.addEventListener('click', closeWeapons);
    if(overlay) overlay.addEventListener('click', (e)=>{ if(e.target===overlay) closeWeapons(); });
    document.addEventListener('keydown', (e)=>{ if(e.key==='Escape') closeWeapons(); });

    const body = document.querySelector('#attacksTable tbody');
    if(body){
      body.addEventListener('change', ()=>{ if(overlay.style.display !== 'none') renderWeaponsList(); });
      body.addEventListener('input', ()=>{ if(overlay.style.display !== 'none') renderWeaponsList(); });
      const observer = new MutationObserver(()=>{ if(overlay.style.display !== 'none') renderWeaponsList(); });
      observer.observe(body, { childList: true });
    }
  }

  // ---------------------------------------------------------------------
  // Actions section collapse/reveal (moved out of the main view since the
  // Weapons panel now covers day-to-day combat use)
  // ---------------------------------------------------------------------
  function wireActionsCollapse(){
    const card = document.getElementById('actionsCard');
    const bar = document.getElementById('actionsCollapsedBar');
    const showBtn = document.getElementById('btnShowActions');
    if(!card || !bar || !showBtn) return;
    showBtn.addEventListener('click', ()=>{
      card.style.display = '';
      bar.style.display = 'none';
      card.scrollIntoView({behavior:'smooth', block:'start'});
    });
  }

  function init(){
    wireWeaponsChrome();
    wireActionsCollapse();
  }

  if(document.readyState === 'loading'){
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }

})();

// ============================================================================
// "+ Add Item" picker — lets a player add gear gained mid-campaign without
// hand-filling a blank row. Three categories: Weapon (adds a computed
// Attacks row, same math as the automatic starting-weapon sync in
// js/app.js), Item, and Magic Item (both append a line to the Equipment
// notes field). Self-contained: doesn't touch js/app.js.
// ============================================================================

const ITEM_LIST = [
  "Rope (50 ft.)", "Torch", "Rations (1 day)", "Waterskin", "Bedroll",
  "Thieves' Tools", "Healer's Kit", "Crowbar", "Grappling Hook", "Lantern",
  "Oil (flask)", "Tinderbox", "Manacles", "Climber's Kit", "Component Pouch",
  "Spellbook", "Shovel", "Fishing Tackle", "Signal Whistle", "Sack"
];

const MAGIC_ITEMS = [
  { name: "Potion of Healing", effect: "Regain 2d4+2 hit points when you drink it." },
  { name: "Bag of Holding", effect: "Interior space holds up to 500 lb. (weighs 15 lb. regardless)." },
  { name: "Cloak of Protection", effect: "+1 to AC and saving throws (requires attunement)." },
  { name: "Wand of Magic Missiles", effect: "7 charges; expend 1+ to cast Magic Missile at that level." },
  { name: "Ring of Protection", effect: "+1 to AC and saving throws (requires attunement)." },
  { name: "Boots of Elvenkind", effect: "Advantage on Stealth checks that rely on moving silently." },
  { name: "Cloak of Elvenkind", effect: "Advantage on Stealth checks; disadvantage on checks to see you while worn (hood up)." },
  { name: "Potion of Greater Healing", effect: "Regain 4d4+4 hit points when you drink it." },
  { name: "Bag of Tricks", effect: "Reach in and pull out a random small animal (rolled)." },
  { name: "Immovable Rod", effect: "Push the button to fix it in place mid-air; holds up to 8,000 lb." }
];

(function(){

  function appendToEquipmentNotes(line){
    const ta = document.querySelector('[name="equipment"]');
    if(!ta) return;
    ta.value = ta.value ? `${ta.value}\n${line}` : line;
    ta.dispatchEvent(new Event('input', { bubbles: true }));
  }

  function fmtBonus(n){ return (n>=0?'+':'') + n; }

  function addWeaponRow(weaponName){
    const w = (typeof WEAPONS !== 'undefined' && WEAPONS[weaponName]) || (typeof MARTIAL_WEAPONS !== 'undefined' && MARTIAL_WEAPONS[weaponName]);
    if(!w) return;
    let strMod = 0, dexMod = 0, pb = 2;
    try { strMod = currentAbilityMod('str'); dexMod = currentAbilityMod('dex'); } catch(e){}
    try { pb = profBonusFor(document.querySelector('[name="classLevel"]').value); } catch(e){}
    const mod = w.finesse ? Math.max(strMod, dexMod) : (w.ranged ? dexMod : strMod);
    const atkBonus = fmtBonus(pb + mod);
    const dmgText = `${w.dmg} ${fmtBonus(mod)} ${w.type}`;

    const body = (typeof attacksBody !== 'undefined') ? attacksBody : document.querySelector('#attacksTable tbody');
    if(!body) return;
    let tr;
    try { tr = makeAttackRow({ name: weaponName, bonus: atkBonus, dmg: dmgText }); }
    catch(e){ return; }
    body.appendChild(tr);
    if(typeof showToast === 'function') showToast(`${weaponName} added to Attacks (assumes proficiency).`);
  }

  // ---------------------------------------------------------------------
  // Picker UI (category -> list)
  // ---------------------------------------------------------------------
  function showCategoryStep(){
    document.getElementById('itemPickerTitle').textContent = 'What did you pick up?';
    document.getElementById('itemPickerBody').innerHTML = `
      <div class="item-picker-cats">
        <button type="button" data-cat="weapon">🗡️<br>Weapon</button>
        <button type="button" data-cat="item">🎒<br>Item</button>
        <button type="button" data-cat="magic">✨<br>Magic Item</button>
      </div>`;
    document.getElementById('itemPickerBody').querySelectorAll('[data-cat]').forEach(btn=>{
      btn.addEventListener('click', ()=> showListStep(btn.dataset.cat));
    });
  }

  function showListStep(cat){
    const titleEl = document.getElementById('itemPickerTitle');
    const bodyEl = document.getElementById('itemPickerBody');
    let backHtml = `<button type="button" class="item-picker-back">← Back</button>`;
    let listHtml = '';

    if(cat === 'weapon'){
      titleEl.textContent = 'Choose a Weapon';
      const names = [
        ...Object.keys(typeof WEAPONS !== 'undefined' ? WEAPONS : {}),
        ...Object.keys(typeof MARTIAL_WEAPONS !== 'undefined' ? MARTIAL_WEAPONS : {})
      ];
      listHtml = names.map(n=>{
        const w = (WEAPONS && WEAPONS[n]) || (MARTIAL_WEAPONS && MARTIAL_WEAPONS[n]);
        return `<div class="summon-picker-item" data-name="${n}"><span class="sp-name">${n}</span><span class="sp-meta">${w.dmg} ${w.type}</span></div>`;
      }).join('');
    } else if(cat === 'item'){
      titleEl.textContent = 'Choose an Item';
      listHtml = ITEM_LIST.map(n=>`<div class="summon-picker-item" data-name="${n}"><span class="sp-name">${n}</span></div>`).join('');
    } else {
      titleEl.textContent = 'Choose a Magic Item';
      listHtml = MAGIC_ITEMS.map(it=>`<div class="summon-picker-item" data-name="${it.name}"><span class="sp-name">${it.name}</span><span class="sp-meta">${it.effect}</span></div>`).join('');
    }

    bodyEl.innerHTML = backHtml + listHtml;
    bodyEl.querySelector('.item-picker-back').addEventListener('click', showCategoryStep);
    bodyEl.querySelectorAll('.summon-picker-item').forEach(row=>{
      row.addEventListener('click', ()=>{
        const name = row.dataset.name;
        if(cat === 'weapon'){
          addWeaponRow(name);
        } else if(cat === 'item'){
          appendToEquipmentNotes(name);
          if(typeof showToast === 'function') showToast(`${name} added to Equipment.`);
        } else {
          const it = MAGIC_ITEMS.find(m => m.name === name);
          appendToEquipmentNotes(`${name} — ${it ? it.effect : ''}`);
          if(typeof showToast === 'function') showToast(`${name} added to Equipment.`);
        }
        closeItemPicker();
      });
    });
  }

  function openItemPicker(){
    showCategoryStep();
    document.getElementById('itemPickerOverlay').style.display = 'flex';
  }
  function closeItemPicker(){
    document.getElementById('itemPickerOverlay').style.display = 'none';
  }

  function init2(){
    const openBtn = document.getElementById('addItemPicker');
    const closeBtn = document.getElementById('itemPickerClose');
    const overlay = document.getElementById('itemPickerOverlay');
    if(openBtn) openBtn.addEventListener('click', openItemPicker);
    if(closeBtn) closeBtn.addEventListener('click', closeItemPicker);
    if(overlay) overlay.addEventListener('click', (e)=>{ if(e.target===overlay) closeItemPicker(); });
    document.addEventListener('keydown', (e)=>{ if(e.key==='Escape') closeItemPicker(); });
  }

  if(document.readyState === 'loading'){
    document.addEventListener('DOMContentLoaded', init2);
  } else {
    init2();
  }

})();
